  "terms.section1.heading": "ପ୍ଲାଟଫର୍ମ ମଣ୍ଡଳ ଏବଂ ଜନସାଧାରଣ ଭିତ୍ତିଭୂମି |",
  "terms.section2.heading": "2। ଭ ograph ଗୋଳିକ ସୂଚକାଙ୍କ (GI) ଏବଂ ପ୍ରାମାଣିକତା ମାନକ |",
