  "tooltip.confirmDecline": "ପ୍ରତ୍ୟାଖ୍ୟାନ ନିଶ୍ଚିତ କରନ୍ତୁ",
  "tooltip.cancelAccept": "ସ୍ୱୀକୃତି ବାତିଲ କରନ୍ତୁ",
  "tooltip.cancelDecline": "ପ୍ରତ୍ୟାଖ୍ୟାନ ବାତିଲ କରନ୍ତୁ",
  "tooltip.openConcierge": "ସହାୟକ ଖୋଲନ୍ତୁ",
