  "trends.intro.speakText": "ବଜାର ଧାରା ଏବଂ ସାମାଜିକ ପ୍ରେରଣା। ଇନଷ୍ଟାଗ୍ରାମ ଏବଂ ପିନଟେରେଷ୍ଟରେ ଗ୍ରାହକମାନେ କ’ଣ ଖୋଜୁଛନ୍ତି ଜାଣନ୍ତୁ।",
