  "trends.modal.intro": "କୌଣସି ଉତ୍ସାହଜନକ ରିଲ୍ କିମ୍ବା ବୁଟିକ୍ ସଂଗ୍ରହ ପାଇଲେ କି? କାରିଗର ଗୋଷ୍ଠୀ ସହିତ ସେୟାର କରନ୍ତୁ ଯାହାଫଳରେ ଚାହିଦା ଅନୁସାରେ ଉତ୍ପାଦନ ହୋଇପାରିବ।",
