  "pdp.bullet.mto": "ଅର୍ଡର ଅନୁସାରେ ତିଆରି ହୁଏ: ଆପଣଙ୍କ ଅର୍ଡର ପରେ କାମ ଆରମ୍ଭ ହୁଏ, ତେଣୁ ଅନୁରୋଧରେ ପରିବର୍ତ୍ତନ ସମ୍ଭବ।",
  "pdp.bullet.ready": "ପ୍ରସ୍ତୁତ ଷ୍ଟକ୍: କାରିଗର 2 କାର୍ଯ୍ୟ ଦିବସ ମଧ୍ୟରେ ପ୍ୟାକ କରି ପଠାନ୍ତି।",
