  "pdp.material.default": "ପ୍ରାକୃତିକ, ସ୍ଥାନୀୟ ପଦାର୍ଥ",
  "pdp.care.dryClean": "କେବଳ ଡ୍ରାଏ କ୍ଲିନ୍ କରନ୍ତୁ। ମଲମଲରେ ଫୋଡ଼ି ସିଧା ସୂର୍ଯ୍ୟାଲୋକରୁ ଦୂରେଇ ରଖନ୍ତୁ।",
  "pdp.care.handWash": "ଥଣ୍ଡା ପାଣି ଏବଂ ମୃଦୁ ସାବୁନରେ ଧୀରେ ହାତରେ ଧୋଇଦିଅନ୍ତୁ। ଛାଇରେ ଶୁଖାନ୍ତୁ।",
  "pdp.care.wipe": "ମୃଦୁ ଶୁଖିଲା କପଡ଼ାରେ ପୋଛନ୍ତୁ। ଯତ୍ନରେ ରଖନ୍ତୁ; ଡିଶ୍‌ୱାସରରେ ପକାନ୍ତୁ ନାହିଁ।",
  "pdp.care.polish": "କେବେକେବେ ଶୁଖିଲା କପଡ଼ାରେ ଚକଚକିଆ କରନ୍ତୁ। ପାଣି ଏବଂ ଅମ୍ଳୀୟ କ୍ଲିନରଠାରୁ ଦୂରେଇ ରଖନ୍ତୁ।",
  "pdp.care.dry": "ଓଦାପଣରୁ ଦୂରେଇ ରଖନ୍ତୁ। ମୃଦୁ ବ୍ରସରେ ଧୂଳି ପୋଛନ୍ତୁ।",
  "pdp.care.frame": "କାଚ ପଛରେ ଫ୍ରେମ କରନ୍ତୁ। ଓଦା କାନ୍ଥ ଏବଂ ସିଧା ସୂର୍ଯ୍ୟାଲୋକରୁ ଦୂରେଇ ରଖନ୍ତୁ।",
  "pdp.care.default": "ଯତ୍ନରେ ରଖନ୍ତୁ। ମୃଦୁ ଶୁଖିଲା କପଡ଼ାରେ ଧୀରେ ସଫା କରନ୍ତୁ।",
  "pdp.review.1.title": "ଫଟୋଠାରୁ ମଧ୍ୟ ସୁନ୍ଦର",
  "pdp.review.1.body": "{craft} କାମ ପାଖରୁ ଦେଖିଲେ ଅଧିକ ସୂକ୍ଷ୍ମ ଦେଖାଯାଏ। ଛୋଟ ଅସମାନତାଗୁଡ଼ିକ ଦର୍ଶାଏ ଯେ ଏହା ହାତରେ ତିଆରି। ବହୁତ ଯତ୍ନରେ ପ୍ୟାକ କରାଯାଇଥିଲା।",
  "pdp.review.2.title": "ପ୍ରତି ଟଙ୍କାର ଉପଯୋଗୀ",
  "pdp.review.2.body": "ପଇସା ସିଧାସଳଖ {artisan}ଙ୍କୁ ଯାଉଥିବା ଜାଣିବା ପରେ ନିଷ୍ପତ୍ତି ସହଜ ହେଲା। ମ୍ୟୁଜିୟମ୍ ସ୍ତରର ଗୁଣବତ୍ତା।",
  "pdp.review.3.title": "ସୁନ୍ଦର, ଟିକେ ବିଳମ୍ବରେ ଆସିଲା",
  "pdp.review.3.body": "ଆକଳନଠାରୁ ତିନି ଦିନ ପରେ ପହଞ୍ଚିଲା, କିନ୍ତୁ କାରିଗର ସନ୍ଦେଶ ପଠାଇ କାରଣ କହିଥିଲେ। ସାମଗ୍ରୀ ନିଜେ ଅଦ୍ଭୁତ।",
  "pdp.review.4.title": "ମୋହର ଯାଞ୍ଚ କଲି, ସବୁ ଆସଲ",
  "pdp.review.4.body": "ପାଇବା ପରେ ମୂଳପ୍ରମାଣ ରେକର୍ଡ ଯାଞ୍ଚ କଲି ଏବଂ ତାଲିକା ସହିତ ସଠିକ୍ ମେଳ ଖାଇଲା। ଅନ୍ତତଃ ଅନଲାଇନ ହସ୍ତକଳା କ୍ରୟରେ ବିଶ୍ୱାସ।",
  "pdp.review.5.title": "ଭଲ, କିନ୍ତୁ ମାପ ଯାଞ୍ଚ କରନ୍ତୁ",
  "pdp.review.5.body": "ଉତ୍କୃଷ୍ଟ କାରିଗରୀ, କିନ୍ତୁ ଆଶାଠାରୁ ଛୋଟ। ଅର୍ଡର ପୂର୍ବରୁ ବିବରଣୀ ସାରଣୀରେ ମାପ ପଢ଼ନ୍ତୁ।",
  "pdp.qa.1.q": "ଏହା ହାତରେ ତିଆରି ନା ଯନ୍ତ୍ରରେ?",
  "pdp.qa.1.a": "ସମ୍ପୂର୍ଣ୍ଣ ହାତରେ ତିଆରି। ଜିଆଇ ଟାଗ୍ ଏବଂ ମୂଳପ୍ରମାଣ ମୋହର ଦୁଇଟି ମଧ୍ୟ କୌଶଳକୁ ନିଶ୍ଚିତ କରନ୍ତି।",
  "pdp.qa.2.q": "ମୁଁ ଅନ୍ୟ ରଙ୍ଗ ମାଗିପାରିବି କି?",
  "pdp.qa.2.aMto": "ହଁ, ଅର୍ଡର ଅନୁସାରେ ତିଆରି ସାମଗ୍ରୀରେ ପରିବର୍ତ୍ତନ ସମ୍ଭବ — ଅର୍ଡର ଟିପ୍ପଣୀରେ ଲେଖନ୍ତୁ।",
  "pdp.qa.2.aReady": "ଏହା ପ୍ରସ୍ତୁତ ଷ୍ଟକ୍ ସାମଗ୍ରୀ, ତେଣୁ ରଙ୍ଗ ଦେଖାଯାଇଥିବା ପରି ହିଁ ଅଛି। ବିଶେଷ ଅର୍ଡର ପାଇଁ କାରିଗରକୁ ସନ୍ଦେଶ ପଠାନ୍ତୁ।",
  "pdp.qa.3.q": "ପଠାଇବା ପାଇଁ ଏହାକୁ କିପରି ପ୍ୟାକ କରାଯାଏ?",
  "pdp.qa.3.a": "କପଡ଼ାରେ, ତାପରେ ବବଲ୍ ରାପ୍‌ରେ ଗୁଡ଼ାଇ ଦୁଇ ପାର୍ଶ୍ୱ ବକ୍ସରେ। ଭଙ୍ଗୁର ସାମଗ୍ରୀ ପାଇଁ ବିଶେଷ କ୍ରେଟ୍।",
  "pdp.qa.4.q": "ଧୋଇଲା ପରେ ରଙ୍ଗ ଫିକା ପଡ଼ିବ କି?",
  "pdp.qa.4.a": "ପ୍ରାକୃତିକ ରଙ୍ଗ ବର୍ଷ ବର୍ଷ ଧରି ଟିକେ ମୋଳାଏ, ଏହା ସ୍ୱାଭାବିକ। ରଙ୍ଗ ବଜାୟ ରଖିବା ପାଇଁ ଯତ୍ନ ନିର୍ଦ୍ଦେଶ ପାଳନ କରନ୍ତୁ।",
