  "pdp.sustainability.lowWaste": "ଗ୍ରାମୀଣ ଜୀବିକାକୁ ସହାୟତା",
  "pdp.trivia.heading": "ଆପଣ ଜାଣନ୍ତି କି?",
  "craft.weaving.funFact": "ବନାରସୀ ବ୍ରୋକେଡ୍ ବୁଣାକାରମାନେ ସୂକ୍ଷ୍ମ ଜରି କାମ ଥିବା ଏକ ରେଶମ ଶାଢ଼ି ପୂରଣ କରିବାକୁ ଏକ ମାସ ପର୍ଯ୍ୟନ୍ତ ସମୟ ନେଇପାରନ୍ତି।",
  "craft.block-printing.funFact": "ଏକ ଅଜରଖ ବ୍ଲକ୍-ପ୍ରିଣ୍ଟ ଡିଜାଇନ୍ ଏହାର ପୂର୍ଣ୍ଣ ଗାଢ଼ ରଙ୍ଗ ପାଇଁ ରଙ୍ଗ, ଧୋଇବା ଏବଂ ଶୁଖାଇବାର 16ଟି ପର୍ଯ୍ୟାୟ ପର୍ଯ୍ୟନ୍ତ ଆବଶ୍ୟକ କରିପାରେ।",
  "craft.pottery.funFact": "ନିଜାମାବାଦର କଳା ମାଟି ପାତ୍ରଗୁଡ଼ିକ ଏହାର ଚମକଦାର କଳା ରଙ୍ଗ ଧୂଆଁରେ ପୂର୍ଣ୍ଣ, ଅମ୍ଳଜାନ ବିହୀନ ଭାଟିରେ ପୋଡ଼ାଯିବାରୁ ପାଏ, କୌଣସି ରଙ୍ଗ କିମ୍ବା ଗ୍ଲେଜ୍‌ରୁ ନୁହେଁ।",
  "craft.metalwork.funFact": "ବିଦରୀ ଶିଳ୍ପର ରୂପା ଖୋଦନ କାର୍ଯ୍ୟ ବିଦର ଦୁର୍ଗ ନିକଟରେ ମିଳୁଥିବା ବିଶେଷ ମାଟିରେ କଳା କରାଯାଇଥିବା ମିଶ୍ର ଧାତୁରେ କରାଯାଏ।",
  "craft.woodwork.funFact": "ଚନ୍ନାପଟଣାର କାଠ ଖେଳନା ଆଜି ମଧ୍ୟ 200 ବର୍ଷ ପୁରୁଣା ଖରାଦ କୌଶଳରେ ଉଦ୍ଭିଦଜାତ ରଙ୍ଗରେ ପାଲିସ୍ କରାଯାଏ।",
  "craft.embroidery.funFact": "ଲକ୍ଷ୍ନୌର ଏକ ଚିକନକାରୀ ପୋଷାକରେ ସୂଚି ଦ୍ୱାରା ହିଁ କରାଯାଇଥିବା ଡଜନ ଡଜନ ଭିନ୍ନ ଭିନ୍ନ ସୂଚିକର୍ମ ଟାଙ୍କା ଥାଇପାରେ।",
  "craft.painting.funFact": "ପାରମ୍ପରିକ ମଧୁବନୀ ଚିତ୍ରକଳା ବିହାରର ମହିଳାମାନେ ନିଜ ଘରର ମାଟି କାନ୍ଥରେ ଆଙ୍କିଥିବା ଚିତ୍ରରୁ ଆରମ୍ଭ ହୋଇଥିଲା।",
  "craft.basketry.funFact": "ମୁଞ୍ଜ ଘାସ ଟୋକେଇ ବୁଣା ଏକ ବଣୁଆ ବନ୍ୟା ଅଞ୍ଚଳର ଘାସକୁ ସ୍ଥାୟୀ, ସମ୍ପୂର୍ଣ୍ଣ ଜୈବ-ବିଘଟନଶୀଳ ଘରୋଇ ସାମଗ୍ରୀରେ ପରିଣତ କରେ।",
  "craft.jewellery.funFact": "କଟକର ରୂପା ତାରକଶୀ କେଶଠାରୁ ମଧ୍ୟ ପତଳା ରୂପା ତାରରେ ଗଢ଼ାଯାଏ।",
  "craft.leather.funFact": "କୋଲହାପୁରୀ ଚପଲ ପାରମ୍ପରିକ ଭାବରେ ଗୋଟିଏ ମଧ୍ୟ କଣ୍ଟା କିମ୍ବା ମେସିନ୍ ସିଲାଇ ବିନା ସମ୍ପୂର୍ଣ୍ଣ ହାତରେ ସିଲାଇ ହୋଇଥାଏ।",
  "craft.stone.funFact": "ଆଗ୍ରାର ପଥର ଖୋଦନ ଶିଳ୍ପୀମାନେ ଆଜି ମଧ୍ୟ ତାଜମହଲକୁ ସୁସଜ୍ଜିତ କରୁଥିବା ସେହି ପିଏତ୍ରା ଦୁରା କୌଶଳ ବ୍ୟବହାର କରନ୍ତି।",
  "craft.bamboo.funFact": "ଏକ ବାଉଁଶ ଗଛ ମାତ୍ର 3-5 ବର୍ଷରେ ଶିଳ୍ପ ବ୍ୟବହାର ପାଇଁ ପ୍ରସ୍ତୁତ ହୋଇପାରେ, ଯାହା କଠିନ କାଠ ଗଛଠାରୁ ଅନେକ ଶୀଘ୍ର।",
  "tips.modal.title": "ଆଜିର ପରାମର୍ଶ",
  "tips.modal.gotIt": "ବୁଝିଲି",
  "tips.priceFloor": "ସର୍ବଦା ଆପଣଙ୍କ ଖର୍ଚ୍ଚ ସୀମାଠାରୁ ଅଧିକ ମୂଲ୍ୟ ରଖନ୍ତୁ — କଞ୍ଚାମାଲ, ଆପଣଙ୍କ ସମୟ ଏବଂ ପ୍ଲାଟଫର୍ମ ଶୁଳ୍କ — ମନ୍ଦା ମାସରେ ମଧ୍ୟ।",
  "tips.trackIncome": "ପ୍ରତ୍ୟେକ ବିକ୍ରୟ ଲେଖି ରଖନ୍ତୁ, ଛୋଟ ହେଲେ ମଧ୍ୟ। ଏକ ସରଳ ଆୟ ରେକର୍ଡ ଆପଣଙ୍କୁ ଦୁର୍ବଳ ଋତୁ ପାଇଁ ଯୋଜନା କରିବାରେ ଏବଂ ଋଣ ପାଇଁ ଆୟ ପ୍ରମାଣ କରିବାରେ ସାହାଯ୍ୟ କରେ।",
  "tips.bulkOrders": "ବଲ୍କ ଏବଂ ପ୍ରାତିଷ୍ଠାନିକ ଅର୍ଡର ସ୍ଥିର ଭାବରେ ଏବଂ ଆଗରୁ ଦେୟ ଦିଅନ୍ତି। ଆପଣଙ୍କ କ୍ଷମତା ଏବଂ ପ୍ରସ୍ତୁତି ସମୟକୁ ଅଦ୍ୟତନ ରଖନ୍ତୁ ଯାହାଫଳରେ ଗ୍ରାହକ ଆପଣଙ୍କୁ ଖୋଜିପାରିବେ।",
  "tips.photoQuality": "ସ୍ପଷ୍ଟ, ଭଲ ଆଲୋକରେ ଏବଂ ଅନେକ କୋଣରୁ ନିଆଯାଇଥିବା ଫଟୋ ସହିତ ତାଲିକା ଶୀଘ୍ର ବିକ୍ରି ହୁଏ। ପ୍ରାକୃତିକ ଆଲୋକ ଫ୍ଲାସ୍‌ଠାରୁ ଭଲ କାମ କରେ।",
  "tips.respondFast": "ଆପଣ ଏକ ଦିନ ମଧ୍ୟରେ ପ୍ରଶ୍ନର ଉତ୍ତର ଦେଲେ ଗ୍ରାହକ ଅର୍ଡର ସମ୍ପୂର୍ଣ୍ଣ କରିବାର ସମ୍ଭାବନା ଅଧିକ ଥାଏ।",
  "tips.saveSavings": "ପ୍ରତ୍ୟେକ ଦେୟର ଏକ ଛୋଟ ଅଂଶ ସଞ୍ଚୟ ଭାବରେ ଅଲଗା ରଖନ୍ତୁ — 5% ମଧ୍ୟ ଏକାଠି ହୋଇ ଅର୍ଡର ମଧ୍ୟରେ ଆପଣଙ୍କୁ ସାହାଯ୍ୟ କରେ।",
  "tips.giPremium": "GI ଟ୍ୟାଗ୍ ମୂଳ ସ୍ଥାନର ପ୍ରମାଣ ଯାହାକୁ ଗ୍ରାହକ ବିଶ୍ୱାସ କରନ୍ତି। ପ୍ରମାଣିତ ସାମଗ୍ରୀର ମୂଲ୍ୟ ପ୍ରାୟତଃ ଅଧିକ ରଖାଯାଇପାରେ — ଆପଣଙ୍କ ସାମଗ୍ରୀକୁ କମ୍ ମୂଲ୍ୟାଙ୍କନ କରନ୍ତୁ ନାହିଁ।",
  "tips.restockEarly": "କଞ୍ଚାମାଲ ସରିବା ପୂର୍ବରୁ ପୁଣି ମଗାଇବା ଆରମ୍ଭ କରନ୍ତୁ, ବିଶେଷତଃ ମାଗଣା ବଢ଼ୁଥିବା ପର୍ବ ଏବଂ ବିବାହ ଋତୁ ପୂର୍ବରୁ।",
  "tips.clusterSupport": "ଆପଣଙ୍କ କ୍ଲଷ୍ଟର ସଂଯୋଜକ ବଲ୍କ ସାମଗ୍ରୀ କ୍ରୟ ଏବଂ ତାଲିମରେ ସାହାଯ୍ୟ କରିପାରନ୍ତି — ଏକ ସମସ୍ୟା ଗମ୍ଭୀର ହେବା ପୂର୍ବରୁ ଯୋଗାଯୋଗ କରନ୍ତୁ।",
  "tips.storySells": "କାହାଣୀ ଥିବା ସାମଗ୍ରୀ ପାଇଁ ଗ୍ରାହକ ଅଧିକ ଦେୟ ଦିଅନ୍ତି। ଆପଣଙ୍କ କୌଶଳ କିମ୍ବା ଶିଳ୍ପ ଇତିହାସ ବିଷୟରେ ଏକ ଛୋଟ ଟିପ୍ପଣୀ ଆପଣଙ୍କ ତାଲିକାରେ ଯୋଡ଼ନ୍ତୁ।",
  "income.baseline.step": "ପୂର୍ବ ଆୟ",
  "income.baseline.question": "କଳାକୃତି ପୂର୍ବରୁ, ଆପଣଙ୍କ ହସ୍ତଶିଳ୍ପରୁ ମାସକୁ କେତେ ରୋଜଗାର ହେଉଥିଲା?",
  "income.baseline.why": "ଏହା ଦେଖାଏ କଳାକୃତି ଆପଣଙ୍କ ଆୟରେ କେତେ ଯୋଗ କରେ। କେବଳ ଆପଣ ନିଜ ଉତ୍ତର ଦେଖିପାରିବେ; ସରକାର କେବଳ ଅଜ୍ଞାତ ମୋଟ ସଂଖ୍ୟା ଦେଖନ୍ତି।",
