  "income.card.noBaseline": "ଆପଣଙ୍କ ବୃଦ୍ଧି ଦେଖିବାକୁ କଳାକୃତି ପୂର୍ବରୁ କେତେ ରୋଜଗାର କରୁଥିଲେ ଜଣାନ୍ତୁ।",
