  "finance.title": "ଋଣ ଏବଂ କିସ୍ତି",
  "finance.intro": "ଆପଣଙ୍କ ସରକାରୀ ଅର୍ଥ ନିଗମରୁ ନିଆଯାଇଥିବା ଋଣ ଯୋଡନ୍ତୁ, ଦେଖନ୍ତୁ ଆପଣଙ୍କ ବିକ୍ରୟ ମାସିକ କିସ୍ତି ପୂରଣ କରୁଛି କି ନାହିଁ।",
