  "finance.reference": "ଋଣ କିମ୍ବା ଆକାଉଣ୍ଟ ନମ୍ବର",
  "finance.referenceHint": "ଆମେ କେବଳ ଶେଷ 4ଟି ଅକ୍ଷର ରଖୁ। ସମ୍ପୂର୍ଣ୍ଣ ନମ୍ବର କଦାପି ସାଇତା ଯାଏ ନାହିଁ।",
